  v_missing_dept     NUMBER;
  v_expected_match   NUMBER;
  v_expected_missing NUMBER;
  v_expected_null    NUMBER;
  v_actual           NUMBER;
  l_failures         NUMBER := 0;

  PROCEDURE check_result(
    p_name     VARCHAR2,
    p_expected NUMBER,
    p_actual   NUMBER
  ) IS
  BEGIN
    IF p_expected = p_actual THEN
      DBMS_OUTPUT.PUT_LINE(
        'PASS: ' || p_name ||
        ', expected ' || TO_CHAR(p_expected) ||
        ', actual ' || TO_CHAR(p_actual)
      );
    ELSE
      DBMS_OUTPUT.PUT_LINE(
        'FAIL: ' || p_name ||
        ', expected ' || TO_CHAR(p_expected) ||
        ', actual ' || TO_CHAR(p_actual)
      );
      l_failures := l_failures + 1;
    END IF;
  END check_result;
BEGIN
  SAVEPOINT test_block_start;

  -- Find a department_id that has at least one employee.
  BEGIN
    SELECT MIN(department_id)
      INTO v_match_dept
      FROM harness_app.employees
     WHERE department_id IS NOT NULL;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      v_match_dept := NULL;
  END;

  IF v_match_dept IS NULL THEN
    DBMS_OUTPUT.PUT_LINE(
      'FAIL: positive department_id check, setup found no employee with a non-NULL department_id'
    );
    l_failures := l_failures + 1;
  ELSE
    BEGIN
      SELECT COUNT(*)
        INTO v_expected_match
        FROM harness_app.employees
       WHERE department_id = v_match_dept;

      v_actual := harness_app.headcount(v_match_dept);
      check_result(
        p_name     => 'existing department_id',
        p_expected => v_expected_match,
        p_actual   => v_actual
      );
    EXCEPTION
      WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE(
          'FAIL: existing department_id check raised ' ||
          SQLCODE || ': ' || SQLERRM
        );
        l_failures := l_failures + 1;
    END;
  END IF;

  -- Use a department_id below the minimum non-NULL department_id, then
  -- confirm independently that it matches no employee row.
  IF v_match_dept IS NULL THEN
    DBMS_OUTPUT.PUT_LINE(
      'FAIL: no-match department_id check, setup found no non-NULL department_id to derive a missing key from'
    );
    l_failures := l_failures + 1;
  ELSE
    v_missing_dept := v_match_dept - 1;

    BEGIN
      SELECT COUNT(*)
        INTO v_expected_missing
        FROM harness_app.employees
       WHERE department_id = v_missing_dept;

      IF v_expected_missing <> 0 THEN
        DBMS_OUTPUT.PUT_LINE(
          'FAIL: no-match department_id check, setup found rows for missing key ' ||
          TO_CHAR(v_missing_dept) ||
          ', expected 0 missing rows'
        );
        l_failures := l_failures + 1;
      ELSE
        BEGIN
          v_actual := harness_app.headcount(v_missing_dept);
          check_result(
            p_name     => 'department_id matching no employee',
            p_expected => 0,
            p_actual   => v_actual
          );
        EXCEPTION
          WHEN OTHERS THEN
            DBMS_OUTPUT.PUT_LINE(
              'FAIL: department_id matching no employee check raised ' ||
              SQLCODE || ': ' || SQLERRM
            );
            l_failures := l_failures + 1;
        END;
      END IF;
    EXCEPTION
      WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE(
          'FAIL: no-match department_id setup raised ' ||
          SQLCODE || ': ' || SQLERRM
        );
        l_failures := l_failures + 1;
    END;
  END IF;

  -- NULL argument: the function compares with =, so NULL matches no row.
  BEGIN
    SELECT COUNT(*)
      INTO v_expected_null
      FROM harness_app.employees
     WHERE department_id = NULL;

    v_actual := harness_app.headcount(NULL);
    check_result(
      p_name     => 'NULL department_id',
      p_expected => v_expected_null,
      p_actual   => v_actual
    );
  EXCEPTION
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE(
        'FAIL: NULL department_id check raised ' ||
        SQLCODE || ': ' || SQLERRM
      );
      l_failures := l_failures + 1;
  END;

  ROLLBACK TO test_block_start;

  IF l_failures > 0 THEN
    RAISE_APPLICATION_ERROR(
      -20001,
      'headcount test block failed: ' || l_failures || ' check(s) failed'
    );
  END IF;
EXCEPTION
  WHEN OTHERS THEN
    ROLLBACK TO test_block_start;
    DBMS_OUTPUT.PUT_LINE('FAIL: unexpected error: ' || SQLCODE || ': ' || SQLERRM);
    RAISE;
END;
```

The checks cover:

1. An existing `department_id`: the block finds a non-NULL `department_id` that has at least one row in `harness_app.employees`, computes the expected row count independently, calls `harness_app.headcount`, and compares the result. If no such department exists, the setup check prints `FAIL` and counts as a failure.

2. A `department_id` that matches no employees: the block derives a missing key from the minimum non-NULL `department_id`, confirms independently that no employee row has that value, calls `harness_app.headcount`, and expects `0`. If the setup cannot derive or confirm a missing key, it prints `FAIL` and counts as a failure.

3. A `NULL` argument: the block computes the expected count using the same equality semantics as the function, where `department_id = NULL` matches no row, calls `harness_app.headcount(NULL)`, and compares the result.

I have not run the block.

